// ─── ATLAS LOGO SYSTEM ────────────────────────────────────────────────────────
//
// Clean lockup: compass+globe mark positioned before the full ATLAS wordmark.
// Reads as: [◉] ATLAS
//
// Three components:
//   AtlasMark      — the uploaded compass+globe image
//   AtlasWordmark  — mark + full ATLAS word at matching cap height
//   AtlasLogo      — wordmark + optional sub-tag, sized sm/md/lg/xl

// ── 1. The compass+globe mark (using uploaded image) ──────────────────────────
const AtlasMark = ({ size = 32 }) => {
  // Image source - this would need to be imported/included in a real app
  // For now, using a data URI placeholder - replace with actual image path
  const imgSrc = "data:image/svg+xml;base64,";
  
  return (
    <img 
      src={imgSrc}
      width={size} 
      height={size}
      alt="Atlas"
      style={{ 
        flexShrink: 0,
        display: 'block',
        imageRendering: 'crisp-edges',
      }}
    />
  );
};

// ── 2. Mark + ATLAS wordmark (not split) ──────────────────────────────────────
// Simpler lockup: [◉] ATLAS where mark sits before the full word
const AtlasWordmark = ({ capHeight = 32, color = T.text }) => {
  // Mark sized to match cap height, with overshoot allowance for spikes
  const markSize = capHeight * 1.25;
  const uid = `aw${capHeight}`;

  const letterStyle = {
    fontFamily: "'Bricolage Grotesque', sans-serif",
    fontWeight: 700,
    fontSize: capHeight,
    letterSpacing: capHeight * 0.05,
    color,
    lineHeight: 1,
    textTransform: "uppercase",
    display: "inline-block",
  };

  const gap = capHeight * 0.25;

  return (
    <div style={{ display:"flex", alignItems:"center", lineHeight:1, gap }}>
      {/* Mark container */}
      <div style={{
        width: markSize,
        height: markSize,
        display:"flex", alignItems:"center", justifyContent:"center",
        flexShrink: 0,
        marginTop: -capHeight * 0.12,
        marginBottom: -capHeight * 0.12,
      }}>
        <AtlasMark size={markSize} uid={uid}/>
      </div>

      {/* Full ATLAS wordmark */}
      <span style={letterStyle}>ATLAS</span>
    </div>
  );
};

// ── 3. Full logo with optional tagline ───────────────────────────────────────
const AtlasLogo = ({ size = "md" }) => {
  const cfg = {
    sm: { cap: 16, tag: 9,  showTag: false },
    md: { cap: 22, tag: 10, showTag: true  },
    lg: { cap: 46, tag: 12, showTag: true  },
    xl: { cap: 64, tag: 13, showTag: true  },
  }[size] || { cap: 22, tag: 10, showTag: true };

  const tagText = size === "lg" || size === "xl"
    ? "Tracking Infrastructure Platform"
    : "by Spi3L";

  return (
    <div style={{ display:"flex", flexDirection:"column", gap: cfg.cap * 0.18 }}>
      <AtlasWordmark capHeight={cfg.cap} />
      {cfg.showTag && (
        <span style={{
          fontFamily: "'JetBrains Mono', monospace",
          fontSize: cfg.tag,
          color: T.textDim,
          letterSpacing: "0.14em",
          textTransform: "uppercase",
          paddingLeft: 2,
        }}>
          {tagText}
        </span>
      )}
    </div>
  );
};

