const Badge = ({ ch, col = "teal", sm }) => {
  const map = { teal:[T.teal,T.tealDim], amber:[T.amber,T.amberDim], red:[T.red,T.redDim], dim:[T.textDim,"rgba(84,92,120,0.15)"], mid:[T.textMid,"rgba(142,151,180,0.12)"] };
  const [fg, bg] = map[col] || map.teal;
  return <span style={{ background: bg, color: fg, border:`1px solid ${fg}28`, borderRadius:4, padding: sm?"1px 6px":"2px 8px", fontSize: sm?10:11, fontWeight:500, letterSpacing:"0.04em", whiteSpace:"nowrap" }}>{ch}</span>;
};

const Btn = ({ ch, onClick, v="primary", sz="md", ic, disabled, full, style:s={} }) => {
  const [hov, setHov] = useState(false);
  const sizes = { sm:"7px 13px", md:"9px 18px", lg:"12px 24px" };
  const fz    = { sm:12, md:13, lg:14 };
  const vv = {
    primary:   { bg: hov?"#0DD4BC":T.teal,       color:"#04201D", shadow: hov?`0 0 20px ${T.tealGlow}`:"none" },
    secondary: { bg: hov?T.surfaceHover:T.surfaceAlt, color:T.text, border:`1px solid ${hov?T.borderLight:T.border}` },
    ghost:     { bg: hov?T.surfaceAlt:"transparent", color: hov?T.text:T.textMid },
    amber:     { bg: hov?"#F0A050":T.amber, color:"#1a0e00" },
  }[v]||{};
  return (
    <button onClick={onClick} disabled={disabled}
      onMouseEnter={()=>setHov(true)} onMouseLeave={()=>setHov(false)}
      style={{ display:"inline-flex", alignItems:"center", justifyContent:"center", gap:7,
        padding:sizes[sz], fontSize:fz[sz], fontWeight:500, fontFamily:"'Bricolage Grotesque',sans-serif",
        borderRadius:8, border:"none", cursor:disabled?"not-allowed":"pointer",
        opacity:disabled?0.45:1, transition:"all 0.17s ease", width:full?"100%":"auto",
        background:vv.bg, color:vv.color, boxShadow:vv.shadow||"none",
        ...(vv.border?{border:vv.border}:{}), ...s }}>
      {ic && <Ico p={IC[ic]} s={14} c="currentColor" />}{ch}
    </button>
  );
};

const Card = ({ children, style:s={}, onClick, hov:hovProp }) => {
  const [hov, setHov] = useState(false);
  return (
    <div onClick={onClick} onMouseEnter={()=>hovProp&&setHov(true)} onMouseLeave={()=>hovProp&&setHov(false)}
      style={{ background:T.surface, border:`1px solid ${hov&&hovProp?T.borderLight:T.border}`,
        borderRadius:12, transition:"all 0.2s", cursor:onClick?"pointer":"default",
        transform:hov&&hovProp?"translateY(-2px)":"none",
        boxShadow:hov&&hovProp?"0 8px 32px rgba(0,0,0,0.35)":"none", ...s }}>
      {children}
    </div>
  );
};

