const Phase4 = ({ onBack, onFinish }) => {
  const [pct,setPct]=useState(0);
  const [running,setRun]=useState(false);
  const [ready,setReady]=useState(false);
  const generate=()=>{
    setRun(true);let p=0;
    const iv=setInterval(()=>{
      p+=Math.random()*18+7;
      if(p>=100){p=100;clearInterval(iv);setTimeout(()=>{setRun(false);setReady(true);},300);}
      setPct(Math.min(p,100));
    },140);
  };
  const outputs=[["code","GTM Container","42 tags, triggers & variables","18 KB",T.teal],["file","Data Layer Code","Shopify Liquid + JavaScript","12 KB",T.teal],["eye","Validation Functions","Runtime QA & error helpers","4 KB",T.amber],["file","Interactive Docs","Complete event reference (HTML)","85 KB",T.textMid],["chart","QA Checklist","18 test cases (Excel)","8 KB",T.teal]];
  return (
    <div className="fu">
      <h2 style={{ fontFamily:"'Cormorant Garamond',serif",fontSize:24,fontWeight:600,marginBottom:6 }}>Generate Package</h2>
      <p style={{ color:T.textMid,marginBottom:24 }}>Your tracking specification is complete. Generate production-ready code and documentation.</p>
      <Card style={{ overflow:"hidden",marginBottom:20 }}>
        <div style={{ padding:"11px 18px",borderBottom:`1px solid ${T.border}`,background:T.surfaceAlt }}>
          <span style={{ fontSize:10,color:T.textDim,fontWeight:600,letterSpacing:"0.12em" }}>PACKAGE INCLUDES</span>
        </div>
        {outputs.map(([icon,name,desc,size,col],i)=>(
          <div key={i} style={{ padding:"14px 18px",borderBottom:i<outputs.length-1?`1px solid ${T.border}`:"none",
            display:"flex",alignItems:"center",gap:14 }}>
            <div style={{ width:32,height:32,borderRadius:8,background:`${col}18`,border:`1px solid ${col}30`,
              display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0 }}>
              <Ico p={IC[icon]} s={14} c={col} />
            </div>
            <div style={{ flex:1 }}>
              <div style={{ fontWeight:500,marginBottom:2 }}>{name}</div>
              <div style={{ color:T.textMid,fontSize:11 }}>{desc}</div>
            </div>
            {ready&&<div style={{ display:"flex",alignItems:"center",gap:8 }}>
              <span style={{ fontFamily:"'JetBrains Mono',monospace",fontSize:11,color:T.textDim }}>{size}</span>
              <Ico p={IC.check} s={13} c={T.teal} sw={2.5} />
            </div>}
          </div>
        ))}
      </Card>
      {running&&<div style={{ marginBottom:20 }}>
        <div style={{ display:"flex",justifyContent:"space-between",marginBottom:8 }}>
          <span style={{ fontFamily:"'JetBrains Mono',monospace",fontSize:11,color:T.teal,animation:"pulse 1s ease infinite" }}>
            {pct<30?"Building GTM container…":pct<60?"Writing data layer code…":pct<85?"Generating documentation…":"Packaging files…"}
          </span>
          <span style={{ fontFamily:"'JetBrains Mono',monospace",fontSize:11,color:T.textDim }}>{Math.round(pct)}%</span>
        </div>
        <ProgressBar val={pct} />
      </div>}
      {ready&&<div className="fu">
        <Card style={{ padding:20,background:T.tealDim,border:`1px solid ${T.teal}40`,marginBottom:20 }}>
          <div style={{ display:"flex",alignItems:"center",gap:12,marginBottom:14 }}>
            <div style={{ width:32,height:32,borderRadius:"50%",background:T.teal,display:"flex",alignItems:"center",justifyContent:"center" }}>
              <Ico p={IC.check} s={15} c={T.bg} sw={2.5} />
            </div>
            <div>
              <div style={{ fontWeight:600 }}>Package ready!</div>
              <div style={{ color:T.textMid,fontSize:12 }}>acme-commerce-tracking-v1.zip · 127 KB</div>
            </div>
          </div>
          <div style={{ display:"flex",gap:10 }}>
            <Btn ch="Download Package" v="primary" ic="download" />
            <Btn ch="Preview Docs" v="secondary" ic="eye" />
          </div>
        </Card>
        <div style={{ background:T.surfaceAlt,borderRadius:9,padding:16,marginBottom:24,
          fontFamily:"'JetBrains Mono',monospace",fontSize:11,color:T.textMid,lineHeight:2 }}>
          <div style={{ color:T.textDim,fontSize:10,letterSpacing:"0.1em",marginBottom:6 }}>NEXT STEPS</div>
          1. Import <span style={{ color:T.teal }}>gtm-container.json</span> into Google Tag Manager<br/>
          2. Upload <span style={{ color:T.teal }}>data-layer.js</span> to Shopify theme assets<br/>
          3. Add GTM snippet to <span style={{ color:T.teal }}>theme.liquid</span><br/>
          4. Run 18 QA tests from the checklist<br/>
          5. Publish GTM container &amp; go live ✓
        </div>
      </div>}
      <div style={{ display:"flex",justifyContent:"space-between" }}>
        <Btn ch="Back" v="secondary" ic="arrowL" onClick={onBack} />
        {!ready
          ?<Btn ch={running?"Generating…":"Generate Package"} ic="zap" disabled={running} onClick={generate} />
          :<Btn ch="Back to Dashboard" v="ghost" onClick={onFinish} />}
      </div>
    </div>
  );
};

